"""Stage A: raw kiln temperature lines -> JSON lines."""
import json
import re
from datetime import datetime, timedelta
from fractions import Fraction

__all__ = ["transform"]

LO, HI = 0, 1400


def _round1(x):
    if x < 0:
        return -_round1(-x)
    return Fraction(int(x * 10 + Fraction(1, 2)), 10)

def _stamp(text):
    m = re.fullmatch(r"([0-9]{4})-([0-9]{2})-([0-9]{2})[T ]([0-9]{2}):([0-9]{2})", text)
    if not m:
        return None
    try:
        dt = datetime(*(int(g) for g in m.groups()[:5]))
    except ValueError:
        return None
    return dt.strftime("%Y-%m-%dT%H:%M")

def _value(token):
    m = re.fullmatch(r"(-?[0-9]+(?:\.[0-9]+)?)([A-Za-z]+)", token)
    if not m:
        return None
    num, unit = Fraction(m.group(1)), m.group(2)
    if unit == "C":
        v = num
    elif unit == "F":
        v = (num - 32) * 5 / 9
    else:
        return None
    v = _round1(v)
    return v if LO <= v <= HI else None

def _fields(line):
    pairs = {}
    for part in line.split(";"):
        k, sep, v = part.partition("=")
        if not sep:
            return None
        pairs[k.strip()] = v.strip()
    if not {"ts", "kiln", "val"} <= set(pairs):
        return None
    return pairs["ts"], pairs["kiln"], pairs["val"]


def transform(text):
    out = []
    cols = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        got = _fields(line)
        if got is None:
            continue
        stamp, entity, token = got
        ts, value = _stamp(stamp), _value(token)
        if ts is None or value is None or not re.fullmatch(r"[A-Za-z0-9_-]+", entity):
            continue
        out.append(json.dumps({"ts": ts, "entity": entity, "value": float(value)}, sort_keys=True))
    return "".join(line + "\n" for line in out)

