"""Stage A: raw hive weight lines -> JSON lines."""
import json
import re
from datetime import datetime, timedelta
from fractions import Fraction

__all__ = ["transform"]

LO, HI = 5, 120


def _round1(x):
    if x < 0:
        return -_round1(-x)
    return Fraction(int(x * 10 + Fraction(1, 2)), 10)

def _stamp(text):
    m = re.fullmatch(r"([0-9]{4})-([0-9]{2})-([0-9]{2})[T ]([0-9]{2}):([0-9]{2})(Z|[+-][0-9]{2}:[0-9]{2})?", text)
    if not m:
        return None
    try:
        dt = datetime(*(int(g) for g in m.groups()[:5]))
    except ValueError:
        return None
    off = m.group(6)
    if off and off != "Z":
        sign = 1 if off[0] == "+" else -1
        dt -= sign * timedelta(hours=int(off[1:3]), minutes=int(off[4:6]))
    return dt.strftime("%Y-%m-%dT%H:%M")

def _value(token):
    m = re.fullmatch(r"(-?[0-9]+(?:\.[0-9]+)?)([A-Za-z]+)", token)
    if not m:
        return None
    num, unit = Fraction(m.group(1)), m.group(2)
    if unit == "kg":
        v = num
    elif unit == "lb":
        v = num * Fraction(45359237, 100000000)
    else:
        return None
    v = _round1(v)
    return v if LO <= v <= HI else None

def _fields(line, cols):
    parts = [p.strip() for p in line.split(",")]
    if len(parts) != len(cols):
        return None
    row = dict(zip(cols, parts))
    return row["when"], row["hive"], row["reading"]


def transform(text):
    out = []
    cols = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if cols is None:
            cols = [c.strip() for c in line.split(",")]
            if not {"when", "hive", "reading"} <= set(cols):
                return ""
            continue
        got = _fields(line, cols)
        if got is None:
            continue
        stamp, entity, token = got
        ts, value = _stamp(stamp), _value(token)
        if ts is None or value is None or not re.fullmatch(r"[A-Za-z0-9_-]+", entity):
            continue
        out.append(json.dumps({"ts": ts, "entity": entity, "value": float(value)}, sort_keys=True))
    return "".join(line + "\n" for line in out)

solution.pipeline/stage_b.py:
"""Stage B: JSON lines -> per-group summary."""
import json
from fractions import Fraction

__all__ = ["transform"]


def _round1(x):
    if x < 0:
        return -_round1(-x)
    return Fraction(int(x * 10 + Fraction(1, 2)), 10)


def transform(text, config):
    thr = Fraction(str(config["threshold"]))
    recs = [json.loads(line) for line in text.splitlines() if line.strip()]
    groups = {}
    for r in recs:
        groups.setdefault(r["entity"], []).append(r)
    out = []
    for key in sorted(groups):
        rs = groups[key]
        vals = [Fraction(str(r["value"])) for r in rs]
        g = {"key": key}
        g["mean"] = float(_round1(sum(vals) / len(vals)))
        g["count"] = len(rs)
        g["last"] = float(Fraction(str(max(enumerate(rs), key=lambda p: (p[1]["ts"], p[0]))[1]["value"])))
        g["over"] = sum(1 for v in vals if v > thr)
        out.append(g)
    return json.dumps({"groups": out}, indent=2, sort_keys=True) + "\n"

